).join('\n');

const text = `📋 <b>סיכום שבועי — בית חכם IL</b>

השבוע סקרנו ${weeklyProducts.length} מוצרים מעולים:

${productsList}

🌐 <a href="${WEBSITE_URL}">לכל ההשוואות והמדריכים באתר</a>

💡 טיפ: הצטרפו לערוץ כדי לקבל 3 דילים חדשים כל יום!

#בית_חכם #סיכום_שבועי #SmartHomeIL`;

// Clear weekly tracking for next week
staticData.weeklyProducts = [];

return [{ json: { botToken: BOT_TOKEN, channelId: CHANNEL_ID, text } }];

// ===== AliExpress Affiliate API - Search Hot Products =====
// SETUP: Replace APP_KEY and APP_SECRET with your Open Platform credentials
// Get them at: https://openservice.aliexpress.com > App Console > Create App
// ==============================================================

const APP_KEY = 'YOUR_APP_KEY_HERE';
const APP_SECRET = 'YOUR_APP_SECRET_HERE';
const TRACKING_ID = 'default';

// Abort if API not configured
if (APP_KEY === 'YOUR_APP_KEY_HERE') {
  throw new Error('AliExpress API not configured. Set APP_KEY and APP_SECRET first.');
}

// Smart home search keywords (rotates daily)
const keywords = [
  'zigbee smart switch 220v',
  'smart home sensor zigbee',
  'robot vacuum cleaner',
  'smart plug wifi zigbee',
  'smart ir remote control',
  'zigbee temperature sensor',
  'smart roller blind motor',
  'smart led strip wifi',
  'zigbee door sensor',
  'smart thermostat valve'
];

const staticData = $getWorkflowStaticData('global');
if (typeof staticData.apiKeywordIndex !== 'number') {
  staticData.apiKeywordIndex = 0;
}
const keyword = keywords[staticData.apiKeywordIndex % keywords.length];
staticData.apiKeywordIndex = (staticData.apiKeywordIndex + 1) % keywords.length;

// Build API request signature (HMAC-MD5)
const crypto = require('crypto');
const timestamp = new Date().toISOString().replace(/[-T:.Z]/g, '').slice(0, 14);

const params = {
  app_key: APP_KEY,
  format: 'json',
  method: 'aliexpress.affiliate.hotproduct.query',
  sign_method: 'md5',
  timestamp: timestamp,
  v: '2.0',
  keywords: keyword,
  category_ids: '',
  page_no: '1',
  page_size: '5',
  target_currency: 'ILS',
  target_language: 'en',
  tracking_id: TRACKING_ID,
  ship_to_country: 'IL',
  sort: 'SALE_PRICE_ASC'
};

// Sort params and build sign string
const sortedKeys = Object.keys(params).sort();
let signStr = APP_SECRET;
for (const key of sortedKeys) {
  signStr += key + params[key];
}
signStr += APP_SECRET;

const sign = crypto.createHash('md5').update(signStr).digest('hex').toUpperCase();

// Build query string
const qs = Object.entries({...params, sign}).map(([k,v]) => `${k}=${encodeURIComponent(v)}`).join('&');
const apiUrl = `https://api-sg.aliexpress.com/sync?${qs}`;

return [{ json: { apiUrl, keyword, APP_KEY, APP_SECRET, TRACKING_ID } }];

// ===== Format API Hot Deal for Telegram =====
const BOT_TOKEN = 'YOUR_BOT_TOKEN_HERE';
const CHANNEL_ID = '@SmartHomeIL_deals';

const response = $input.item.json;

// Parse API response
const result = response?.aliexpress_affiliate_hotproduct_query_response?.resp_result;
if (!result || result.resp_code !== 200) {
  throw new Error('API returned error: ' + JSON.stringify(result));
}

const products = result.result?.products?.product || [];
if (products.length === 0) {
  return []; // No products found, skip
}

// Pick the best product (highest commission + good rating)
const product = products.sort((a, b) => {
  const scoreA = (parseFloat(a.evaluate_rate) || 0) + (parseFloat(a.commission_rate) || 0);
  const scoreB = (parseFloat(b.evaluate_rate) || 0) + (parseFloat(b.commission_rate) || 0);
  return scoreB - scoreA;
})[0];

const title = product.product_title || 'Smart Home Product';
const price = product.target_sale_price || product.target_original_price || '?';
const currency = product.target_sale_price_currency || 'ILS';
const affiliateUrl = product.promotion_link || product.product_detail_url;
const imageUrl = product.product_main_image_url || '';
const commission = product.commission_rate || '?';
const orders = product.lastest_volume || 0;

const text = `🔥 <b>דיל חם מאליאקספרס!</b>\n\n📦 <b>${title}</b>\n💰 מחיר: ${currency} ${price}\n📊 הזמנות: ${orders}+\n💎 עמלה: ${commission}%\n\n🛒 <a href=\"${affiliateUrl}\">לרכישה עם הנחה ←</a>\n📖 <a href=\"https://ziv-daniel.github.io/smart-income/\">עוד דילים באתר</a>\n\n#בית_חכם #דיל_חם #AliExpress #SmartHomeIL`;

return [{ json: { botToken: BOT_TOKEN, channelId: CHANNEL_ID, text } }];
